    // named places ({ n: HUD label, d: metres after the start line, say: the commentator's lines })
    names: [
      {"n":"Bear Canyon","d":120.0,"say":["Away from Bear Canyon, eight kilometres up the mountain!","Bear Canyon behind, the climb begins!"]},
      {"n":"Windy Point Vista","d":2357.0,"say":["Windy Point! Granite spires and the whole of Tucson far below!","Past Windy Point, the hoodoos standing over the bend!"]},
      {"n":"Geology Vista","d":3062.0,"say":["Geology Vista, balanced rocks on every ridge!","Past Geology Vista, keep it on the road!"]},
      {"n":"Hoodoo Vista","d":4182.0,"say":["Hoodoo Vista! Stone towers all along the ridge!","The hoodoos, and the pines are coming!"]},
      {"n":"Lizard Rock","d":4987.0,"say":["Lizard Rock up on the left, into the pine forest now!","Into the ponderosa pines, the air is cooler up here!"]},
      {"n":"Rose Canyon","d":7274.0,"say":["The Rose Canyon turn, the last kilometre!","Past Rose Canyon, the top is in sight!"]},
      {"n":"San Pedro Vista · 2.242 m","d":7980.0,"say":["San Pedro Vista! The top of the climb!","Over the line at San Pedro Vista, eight kilometres of mountain behind you!"]},
    ],
    // the commentator's own lines on this road (Comm: instead of Vršič's)
    comm: {
      introPass: ["Welcome to {track}! Thirteen cars, eight kilometres up into the Santa Catalina Mountains, and you start {grid}.","Here we are above Bear Canyon, at the foot of {track}. Granite, oaks and pines to the top, and you line up {grid}.","Welcome to the sky island above Tucson, and to {track}! Thirteen cars, one long climb, and you start {grid}."],
      goPass: ["Lights out, and away they go, up the mountain!","And they're off! Next stop, San Pedro Vista!","Green light! The pack charges up the Catalina Highway!","Go, go, go! Eight kilometres of climbing ahead!"],
      introPassTT: ["Welcome to {track}! Eight kilometres up the mountain, just you and the clock.","Here we are at the foot of {track}. {cps} checkpoints between you and San Pedro Vista.","Welcome to {track}! No rivals this time, only the clock and the climb."],
      goPassTT: ["Green light! The clock is running!","Go! Up into the pines!","And you're away! Up the mountain!"],
      introTraffic: ["Welcome to {track}, and the road is open today: cars, motorbikes and a lot of cyclists. Just you and {rival}, first to San Pedro Vista wins!","Here we are at the foot of {track}. A duel with {rival} up the open road. Mind the cyclists on the climb!","Welcome to {track}! No closed road this time: the riders are out in force. Beat {rival} to the top!"],
      introPolice: ["Welcome to {track}! The police want a word with you, and they are right behind. Get to San Pedro Vista without getting caught!","Here we are above Bear Canyon, and the lights are already flashing. Eight kilometres to the top. Do not stop!","Welcome to {track}! A patrol car on your tail, spike strips and roadblocks up the mountain. Run for it!"],
      escaped: ["You made it to San Pedro Vista! The police will have to wait for another day!","Escaped! Up the mountain and away!","What a getaway! All the way up the Catalina Highway!"],
      summitRecord: ["At San Pedro Vista! A new personal best, {time}!","Record run! {time} up the mountain!","What a climb! New personal best, {time}!"],
      summitEven: ["At the top in {time}. That is your record to the thousandth!","{time} at the top, dead level with your best!"],
      summit: ["At the top in {time}, {delta} seconds off your best.","Across the line at San Pedro Vista. {time}, just {delta} short of the record.","That's the top. {time}. {delta} seconds to find next time."],
    },
